content:
258              break;
   259          default:
   260              return NULL;
   261      }
   262      UA_Node *dst = (UA_Node*)dstPtr;
   263      dst->nodeClass = src->nodeClass;
   264
   265      UA_StatusCode retval = UA_Node_copy(src, dst);
   266      if(retval != UA_STATUSCODE_GOOD) {
   267          UA_free(dst);
   268          return NULL;
   269      }
   270      return dst;
   271  }
