   287  static UA_StatusCode
   288  copyCommonVariableAttributes(UA_VariableNode *node,
   289                               const UA_VariableAttributes *attr) {
   290      /* Copy the array dimensions */
   291      UA_StatusCode retval =
   292          UA_Array_copy(attr->arrayDimensions, attr->arrayDimensionsSize,
   293                        (void**)&node->arrayDimensions, &UA_TYPES[UA_TYPES_UINT32]);
   294      if(retval != UA_STATUSCODE_GOOD)
   295          return retval;
   296      node->arrayDimensionsSize = attr->arrayDimensionsSize;
   297
   298      /* Data type and value rank */
   299      retval |= UA_NodeId_copy(&attr->dataType, &node->dataType);
   300      node->valueRank = attr->valueRank;
   301
   302      /* Copy the value */
   303      node->valueSource = UA_VALUESOURCE_DATA;
   304      UA_NodeId extensionObject = UA_NODEID_NUMERIC(0, UA_NS0ID_STRUCTURE);
   305      /* if we have an extension object which is still encoded (e.g. from the nodeset compiler)
   306       * we need to decode it and set the decoded value instead of the encoded object */
   307      UA_Boolean valueSet = false;
   308      if(attr->value.type != NULL && UA_NodeId_equal(&attr->value.type->typeId, &extensionObject)) {
   309
   310          if (attr->value.data == UA_EMPTY_ARRAY_SENTINEL) {
   311              /* do nothing since we got an empty array of extension objects */
   312              return UA_STATUSCODE_GOOD;
   313          }
   314
   315          const UA_ExtensionObject *obj = (const UA_ExtensionObject *)attr->value.data;
   316          if(obj && obj->encoding == UA_EXTENSIONOBJECT_ENCODED_BYTESTRING) {
   317
   318              /* TODO: Once we generate type description in the nodeset compiler,
   319               * UA_findDatatypeByBinary can be made internal to the decoding
   320               * layer. */
   321              const UA_DataType *type = UA_findDataTypeByBinary(&obj->content.encoded.typeId);
   322
   323              if(type) {
   324                  void *dst = UA_Array_new(attr->value.arrayLength, type);
   325                  uint8_t *tmpPos = (uint8_t *)dst;
   326
   327                  for(size_t i=0; i<attr->value.arrayLength; i++) {
   328                      size_t offset =0;
   329                      const UA_ExtensionObject *curr = &((const UA_ExtensionObject *)attr->value.data)[i];
   330                      UA_StatusCode ret = UA_decodeBinary(&curr->content.encoded.body, &offset, tmpPos, type, 0, NULL);
   331                      if(ret != UA_STATUSCODE_GOOD) {
   332                          return ret;
   333                      }
   334                      tmpPos += type->memSize;
   335                  }
   336
   337                  UA_Variant_setArray(&node->value.data.value.value, dst, attr->value.arrayLength, type);
   338                  valueSet = true;
   339              }
   340          }
   341      }
   342
   343      if(!valueSet)
   344          retval |= UA_Variant_copy(&attr->value, &node->value.data.value.value);
   345
   346      node->value.data.value.hasValue = true;
   347
   348      return retval;
   349  }
