   478
   479  static UA_StatusCode
   480  addReferenceTarget(UA_NodeReferenceKind *refs, const UA_ExpandedNodeId *target) {
   481      UA_ExpandedNodeId *targets =
   482          (UA_ExpandedNodeId*) UA_realloc(refs->targetIds,
   483                                          sizeof(UA_ExpandedNodeId) * (refs->targetIdsSize+1));
   484      if(!targets)
   485          return UA_STATUSCODE_BADOUTOFMEMORY;
   486
   487      refs->targetIds = targets;
   488      UA_StatusCode retval =
   489          UA_ExpandedNodeId_copy(target, &refs->targetIds[refs->targetIdsSize]);
   490
   491      if(retval == UA_STATUSCODE_GOOD) {
   492          refs->targetIdsSize++;
   493      } else if(refs->targetIdsSize == 0) {
   494          /* We had zero references before (realloc was a malloc) */
   495          UA_free(refs->targetIds);
   496          refs->targetIds = NULL;
   497      }
   498      return retval;
   499  }
   500
   501  static UA_StatusCode
   502  addReferenceKind(UA_Node *node, const UA_AddReferencesItem *item) {
   503      UA_NodeReferenceKind *refs =
   504          (UA_NodeReferenceKind*)UA_realloc(node->references,
   505                                            sizeof(UA_NodeReferenceKind) * (node->referencesSize+1));
   506      if(!refs)
   507          return UA_STATUSCODE_BADOUTOFMEMORY;
   508      node->references = refs;
   509      UA_NodeReferenceKind *newRef = &refs[node->referencesSize];
   510      memset(newRef, 0, sizeof(UA_NodeReferenceKind));
   511
   512      newRef->isInverse = !item->isForward;
   513      UA_StatusCode retval = UA_NodeId_copy(&item->referenceTypeId, &newRef->referenceTypeId);
   514      retval |= addReferenceTarget(newRef, &item->targetNodeId);
   515
   516      if(retval == UA_STATUSCODE_GOOD) {
   517          node->referencesSize++;
   518      } else {
   519          UA_NodeId_deleteMembers(&newRef->referenceTypeId);
   520          if(node->referencesSize == 0) {
   521              UA_free(node->references);
   522              node->references = NULL;
   523          }
   524      }
   525      return retval;
   526  }
   527
   528  UA_StatusCode
   529  UA_Node_addReference(UA_Node *node, const UA_AddReferencesItem *item) {
   530      UA_NodeReferenceKind *existingRefs = NULL;
   531      for(size_t i = 0; i < node->referencesSize; ++i) {
   532          UA_NodeReferenceKind *refs = &node->references[i];
   533          if(refs->isInverse != item->isForward
   534                  && UA_NodeId_equal(&refs->referenceTypeId, &item->referenceTypeId)) {
   535              existingRefs = refs;
   536              break;
   537          }
   538      }
   539      if(existingRefs != NULL) {
   540          for(size_t i = 0; i < existingRefs->targetIdsSize; i++) {
   541              if(UA_ExpandedNodeId_equal(&existingRefs->targetIds[i],
   542                                         &item->targetNodeId)) {
   543                  return UA_STATUSCODE_BADDUPLICATEREFERENCENOTALLOWED;
   544              }
   545          }
   546          return addReferenceTarget(existingRefs, &item->targetNodeId);
   547      }
   548      return addReferenceKind(node, item);
   549  }
   550
   551  UA_StatusCode
   552  UA_Node_deleteReference(UA_Node *node, const UA_DeleteReferencesItem *item) {
   553      for(size_t i = node->referencesSize; i > 0; --i) {
   554          UA_NodeReferenceKind *refs = &node->references[i-1];
   555          if(item->isForward == refs->isInverse)
   556              continue;
   557          if(!UA_NodeId_equal(&item->referenceTypeId, &refs->referenceTypeId))
   558              continue;
   559
   560          for(size_t j = refs->targetIdsSize; j > 0; --j) {
   561              if(!UA_NodeId_equal(&item->targetNodeId.nodeId, &refs->targetIds[j-1].nodeId))
   562                  continue;
   563
   564              /* Ok, delete the reference */
   565              UA_ExpandedNodeId_deleteMembers(&refs->targetIds[j-1]);
   566              refs->targetIdsSize--;
   567
   568              /* One matching target remaining */
   569              if(refs->targetIdsSize > 0) {
   570                  if(j-1 != refs->targetIdsSize) // avoid valgrind error: Source
   571                                                 // and destination overlap in
   572                                                 // memcpy
   573                      refs->targetIds[j-1] = refs->targetIds[refs->targetIdsSize];
   574                  return UA_STATUSCODE_GOOD;
   575              }
   576
   577              /* Remove refs */
   578              UA_free(refs->targetIds);
   579              UA_NodeId_deleteMembers(&refs->referenceTypeId);
   580              node->referencesSize--;
   581              if(node->referencesSize > 0) {
   582                  if(i-1 != node->referencesSize) // avoid valgrind error: Source
   583                                                  // and destination overlap in
   584                                                  // memcpy
   585                      node->references[i-1] = node->references[node->referencesSize];
   586                  return UA_STATUSCODE_GOOD;
   587              }
   588
   589              /* Remove the node references */
   590              UA_free(node->references);
   591              node->references = NULL;
   592              return UA_STATUSCODE_GOOD;
   593          }
   594      }
   595      return UA_STATUSCODE_UNCERTAINREFERENCENOTDELETED;
   596  }
   597
   598  void UA_Node_deleteReferences(UA_Node *node) {
   599      for(size_t i = 0; i < node->referencesSize; ++i) {
   600          UA_NodeReferenceKind *refs = &node->references[i];
   601          UA_Array_delete(refs->targetIds, refs->targetIdsSize, &UA_TYPES[UA_TYPES_EXPANDEDNODEID]);
   602          UA_NodeId_deleteMembers(&refs->referenceTypeId);
   603      }
   604      if(node->references)
   605          UA_free(node->references);
   606      node->references = NULL;
   607      node->referencesSize = 0;
   608  }
