   190  static UA_StatusCode
   191  clearSlot(UA_NodeMap *ns, UA_NodeMapEntry **slot) {
   192      (*slot)->deleted = true;
   193      cleanupEntry(*slot);
   194      *slot = UA_NODEMAP_TOMBSTONE;
   195      --ns->count;
   196      /* Downsize the hashmap if it is very empty */
   197      if(ns->count * 8 < ns->size && ns->size > 32)
   198          expand(ns); /* Can fail. Just continue with the bigger hashmap. */
   199      return UA_STATUSCODE_GOOD;
   200  }
   201
   202  static UA_NodeMapEntry **
   203  findOccupiedSlot(const UA_NodeMap *ns, const UA_NodeId *nodeid) {
   204      UA_UInt32 h = UA_NodeId_hash(nodeid);
   205      UA_UInt32 size = ns->size;
   206      UA_UInt32 idx = mod(h, size);
   207      UA_UInt32 hash2 = mod2(h, size);
   208
   209      while(true) {
   210          UA_NodeMapEntry *e = ns->entries[idx];
   211          if(!e)
   212              return NULL;
   213          if(e > UA_NODEMAP_TOMBSTONE &&
   214             UA_NodeId_equal(&e->node.nodeId, nodeid))
   215              return &ns->entries[idx];
   216          idx += hash2;
   217          if(idx >= size)
   218              idx -= size;
   219      }
   220
   221      /* NOTREACHED */
   222      return NULL;
   223  }
